package plugins

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Supported plugin scaffold languages.
const (
	LangGo         = "go"
	LangPython     = "python"
	LangTypeScript = "typescript"
)

// ScaffoldOptions configures a new plugin skeleton generated by Scaffold.
type ScaffoldOptions struct {
	Name        string
	Lang        string
	Dir         string
	Description string
}

// ScaffoldResult reports the directory, normalized language, and
// relative file paths created by Scaffold.
type ScaffoldResult struct {
	Dir   string
	Lang  string
	Files []string
}

type scaffoldManifest struct {
	SchemaVersion int                   `json:"schema_version"`
	Name          string                `json:"name"`
	Version       string                `json:"version"`
	Description   string                `json:"description"`
	Command       []string              `json:"command"`
	Capabilities  []string              `json:"capabilities"`
	Sandbox       scaffoldSandboxConfig `json:"sandbox"`
}

// scaffoldSandboxConfig omits omitempty tags so "write_paths": [] and
// "allow_network": false are written explicitly to plugin.json.
type scaffoldSandboxConfig struct {
	WritePaths   []string `json:"write_paths"`
	AllowNetwork bool     `json:"allow_network"`
}

type scaffoldFile struct {
	rel  string
	data []byte
	mode os.FileMode
}

// Scaffold creates a zero-dependency starter plugin directory for the
// selected language (go, python, or typescript). It refuses to overwrite
// an existing non-empty directory.
func Scaffold(opts ScaffoldOptions) (*ScaffoldResult, error) {
	name := strings.TrimSpace(opts.Name)
	if name == "" {
		return nil, fmt.Errorf("plugin scaffold: name is required")
	}
	if len(name) > 128 || !pluginNameRE.MatchString(name) || name == "." || name == ".." {
		return nil, fmt.Errorf("plugin scaffold: name %q is invalid", name)
	}

	lang, err := normalizeScaffoldLang(opts.Lang)
	if err != nil {
		return nil, fmt.Errorf("plugin scaffold: %w", err)
	}

	dir := strings.TrimSpace(opts.Dir)
	if dir == "" {
		dir = filepath.Join(".", name)
	}
	if err := ensureEmptyScaffoldDir(dir); err != nil {
		return nil, fmt.Errorf("plugin scaffold: %w", err)
	}

	description := strings.TrimSpace(opts.Description)
	if description == "" {
		description = fmt.Sprintf("%s plugin for auto-harness", name)
	}

	toolName := scaffoldToolName(name)
	files, err := buildScaffoldFiles(name, lang, description, toolName)
	if err != nil {
		return nil, fmt.Errorf("plugin scaffold: %w", err)
	}

	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("plugin scaffold: %w", err)
	}

	written := make([]string, 0, len(files))
	for _, f := range files {
		target := filepath.Join(dir, f.rel)
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return nil, fmt.Errorf("plugin scaffold: %w", err)
		}
		if err := os.WriteFile(target, f.data, f.mode); err != nil {
			return nil, fmt.Errorf("plugin scaffold: %w", err)
		}
		written = append(written, filepath.ToSlash(f.rel))
	}
	sort.Strings(written)

	return &ScaffoldResult{
		Dir:   dir,
		Lang:  lang,
		Files: written,
	}, nil
}

func normalizeScaffoldLang(lang string) (string, error) {
	switch strings.ToLower(strings.TrimSpace(lang)) {
	case "", LangPython, "py":
		return LangPython, nil
	case LangGo:
		return LangGo, nil
	case LangTypeScript, "ts":
		return LangTypeScript, nil
	default:
		return "", fmt.Errorf("unsupported language %q (want go, python, or typescript)", lang)
	}
}

func ensureEmptyScaffoldDir(dir string) error {
	info, err := os.Stat(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	if !info.IsDir() {
		return fmt.Errorf("%s exists and is not a directory", dir)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	if len(entries) > 0 {
		return fmt.Errorf("directory %s is not empty", dir)
	}
	return nil
}

func scaffoldToolName(pluginName string) string {
	safe := strings.ReplaceAll(pluginName, "-", "_")
	safe = strings.ReplaceAll(safe, ".", "_")
	return safe + "_echo"
}

func buildScaffoldFiles(name, lang, description, toolName string) ([]scaffoldFile, error) {
	var command []string
	switch lang {
	case LangGo:
		command = []string{"go", "run", "."}
	case LangPython:
		command = []string{"python3", "plugin.py"}
	case LangTypeScript:
		command = []string{"node", "dist/plugin.js"}
	default:
		return nil, fmt.Errorf("unsupported language %q", lang)
	}

	manifest := scaffoldManifest{
		SchemaVersion: SchemaVersion,
		Name:          name,
		Version:       "0.1.0",
		Description:   description,
		Command:       command,
		Capabilities:  []string{"tools"},
		Sandbox: scaffoldSandboxConfig{
			WritePaths:   []string{},
			AllowNetwork: false,
		},
	}
	manifestJSON, err := marshalIndent(manifest)
	if err != nil {
		return nil, err
	}

	files := []scaffoldFile{
		{rel: ManifestFile, data: manifestJSON, mode: 0o644},
		{rel: "README.md", data: []byte(renderScaffoldREADME(name, lang, toolName)), mode: 0o644},
	}

	switch lang {
	case LangPython:
		files = append(files, scaffoldFile{
			rel:  "plugin.py",
			data: []byte(renderPythonTemplate(name, description, toolName)),
			mode: 0o755,
		})
	case LangGo:
		files = append(files,
			scaffoldFile{
				rel:  "go.mod",
				data: []byte(fmt.Sprintf("module example.com/plugins/%s\n\ngo 1.22\n", name)),
				mode: 0o644,
			},
			scaffoldFile{
				rel:  "main.go",
				data: []byte(renderGoTemplate(name, description, toolName)),
				mode: 0o644,
			},
		)
	case LangTypeScript:
		pkgJSON, err := json.MarshalIndent(map[string]any{
			"name":    name,
			"version": "0.1.0",
			"private": true,
			"type":    "module",
			"scripts": map[string]string{
				"build": "tsc",
			},
		}, "", "  ")
		if err != nil {
			return nil, err
		}
		tsconfigJSON, err := json.MarshalIndent(map[string]any{
			"compilerOptions": map[string]any{
				"target":           "ES2022",
				"module":           "NodeNext",
				"moduleResolution": "NodeNext",
				"rootDir":          "src",
				"outDir":           "dist",
				"strict":           true,
			},
			"include": []string{"src/**/*"},
		}, "", "  ")
		if err != nil {
			return nil, err
		}
		files = append(files,
			scaffoldFile{rel: "package.json", data: append(pkgJSON, '\n'), mode: 0o644},
			scaffoldFile{rel: "tsconfig.json", data: append(tsconfigJSON, '\n'), mode: 0o644},
			scaffoldFile{
				rel:  filepath.Join("src", "plugin.ts"),
				data: []byte(renderTypeScriptTemplate(name, description, toolName)),
				mode: 0o644,
			},
			scaffoldFile{
				rel:  filepath.Join("dist", "plugin.js"),
				data: []byte(renderJavaScriptTemplate(name, description, toolName)),
				mode: 0o755,
			},
		)
	}

	return files, nil
}

func renderScaffoldREADME(name, lang, toolName string) string {
	return fmt.Sprintf(`# %s

Auto-harness process plugin (%s template).

## Included Files

- plugin.json: Plugin manifest (sandboxed read-only with network disabled by default).
- Sample tool: %s(text: string) -> "%s: <text>"

## Quick Test

Load this plugin directory in auto-harness using:

  harness -plugin-dirs .
`, name, lang, toolName, name)
}

func renderPythonTemplate(name, description, toolName string) string {
	return fmt.Sprintf(`#!/usr/bin/env python3
"""Zero-dependency auto-harness plugin: %s."""

import json
import sys

SCHEMA_VERSION = "1.0"
PLUGIN_NAME = %q
PLUGIN_DESCRIPTION = %q
TOOL_NAME = %q


def write_message(payload):
    sys.stdout.write(json.dumps(payload, separators=(",", ":")) + "\n")
    sys.stdout.flush()


def write_error(req_id, code, message):
    if req_id is None:
        return
    write_message({
        "schema_version": SCHEMA_VERSION,
        "id": req_id,
        "error": {"code": code, "message": message},
    })


def handle_manifest():
    return {
        "schema_version": SCHEMA_VERSION,
        "name": PLUGIN_NAME,
        "description": PLUGIN_DESCRIPTION,
        "tools": [
            {
                "name": TOOL_NAME,
                "description": "Echo text back from the %s plugin.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "text": {
                            "type": "string",
                            "description": "Text to echo back",
                        }
                    },
                    "required": ["text"],
                },
            }
        ],
    }


def handle_tool_execute(params):
    tool = params.get("name", "")
    if tool != TOOL_NAME:
        return {"content": f"unknown tool {tool!r}", "is_error": True}
    args = params.get("arguments") or {}
    text = str(args.get("text", ""))
    return {"content": f"{PLUGIN_NAME}: {text}"}


def main():
    for raw in sys.stdin:
        line = raw.strip()
        if not line:
            continue
        req_id = None
        try:
            req = json.loads(line)
            req_id = req.get("id")
            version = req.get("schema_version")
            if version not in (None, "", "1") and not (isinstance(version, str) and version.startswith("1.")):
                raise ValueError(f"unsupported schema_version {version!r}")
            method = req.get("method", "")
            params = req.get("params") or {}
            if method == "shutdown":
                if req_id is not None:
                    write_message({"schema_version": SCHEMA_VERSION, "id": req_id, "result": {}})
                break
            if method == "manifest":
                result = handle_manifest()
            elif method == "tool.execute":
                result = handle_tool_execute(params)
            else:
                write_error(req_id, -32601, f"unknown method {method!r}")
                continue
            if req_id is not None:
                write_message({"schema_version": SCHEMA_VERSION, "id": req_id, "result": result})
        except Exception as exc:
            write_error(req_id, -32000, str(exc))


if __name__ == "__main__":
    main()
`, name, name, description, toolName, name)
}

func renderGoTemplate(name, description, toolName string) string {
	return fmt.Sprintf(`package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

const (
	schemaVersion     = "1.0"
	pluginName        = %q
	pluginDescription = %q
	toolName          = %q
)

type request struct {
	SchemaVersion string          `+"`json:\"schema_version,omitempty\"`"+`
	ID            *int            `+"`json:\"id,omitempty\"`"+`
	Method        string          `+"`json:\"method\"`"+`
	Params        json.RawMessage `+"`json:\"params,omitempty\"`"+`
}

type rpcError struct {
	Code    int    `+"`json:\"code,omitempty\"`"+`
	Message string `+"`json:\"message\"`"+`
}

type response struct {
	SchemaVersion string    `+"`json:\"schema_version,omitempty\"`"+`
	ID            *int      `+"`json:\"id,omitempty\"`"+`
	Result        any       `+"`json:\"result,omitempty\"`"+`
	Error         *rpcError `+"`json:\"error,omitempty\"`"+`
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 64*1024), 4*1024*1024)
	enc := json.NewEncoder(os.Stdout)

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var req request
		if err := json.Unmarshal([]byte(line), &req); err != nil {
			continue
		}
		if req.SchemaVersion != "" && req.SchemaVersion != "1" && !strings.HasPrefix(req.SchemaVersion, "1.") {
			if req.ID != nil {
				_ = enc.Encode(response{
					SchemaVersion: schemaVersion,
					ID:            req.ID,
					Error:         &rpcError{Code: -32000, Message: fmt.Sprintf("unsupported schema_version %%q", req.SchemaVersion)},
				})
			}
			continue
		}
		switch req.Method {
		case "shutdown":
			if req.ID != nil {
				_ = enc.Encode(response{SchemaVersion: schemaVersion, ID: req.ID, Result: map[string]any{}})
			}
			return
		case "manifest":
			_ = enc.Encode(response{
				SchemaVersion: schemaVersion,
				ID:            req.ID,
				Result: map[string]any{
					"schema_version": schemaVersion,
					"name":           pluginName,
					"description":    pluginDescription,
					"tools": []map[string]any{
						{
							"name":        toolName,
							"description": fmt.Sprintf("Echo text back from the %%s plugin.", pluginName),
							"parameters": map[string]any{
								"type": "object",
								"properties": map[string]any{
									"text": map[string]any{
										"type":        "string",
										"description": "Text to echo back",
									},
								},
								"required": []string{"text"},
							},
						},
					},
				},
			})
		case "tool.execute":
			var params struct {
				Name      string `+"`json:\"name\"`"+`
				Arguments struct {
					Text string `+"`json:\"text\"`"+`
				} `+"`json:\"arguments\"`"+`
			}
			if err := json.Unmarshal(req.Params, &params); err != nil {
				if req.ID != nil {
					_ = enc.Encode(response{
						SchemaVersion: schemaVersion,
						ID:            req.ID,
						Error:         &rpcError{Code: -32000, Message: err.Error()},
					})
				}
				continue
			}
			var result map[string]any
			if params.Name != toolName {
				result = map[string]any{
					"content":  fmt.Sprintf("unknown tool %%q", params.Name),
					"is_error": true,
				}
			} else {
				result = map[string]any{
					"content": fmt.Sprintf("%%s: %%s", pluginName, params.Arguments.Text),
				}
			}
			_ = enc.Encode(response{SchemaVersion: schemaVersion, ID: req.ID, Result: result})
		default:
			if req.ID != nil {
				_ = enc.Encode(response{
					SchemaVersion: schemaVersion,
					ID:            req.ID,
					Error:         &rpcError{Code: -32601, Message: fmt.Sprintf("unknown method %%q", req.Method)},
				})
			}
		}
	}
}
`, name, description, toolName)
}

func renderTypeScriptTemplate(name, description, toolName string) string {
	return fmt.Sprintf(`import * as readline from "node:readline";

const SCHEMA_VERSION = "1.0";
const PLUGIN_NAME = %q;
const PLUGIN_DESCRIPTION = %q;
const TOOL_NAME = %q;

interface RPCRequest {
  schema_version?: unknown;
  id?: number;
  method?: string;
  params?: {
    name?: string;
    arguments?: { text?: unknown };
  };
}

function writeMessage(payload: Record<string, unknown>): void {
  process.stdout.write(JSON.stringify(payload) + "\n");
}

function writeError(id: number | undefined, code: number, message: string): void {
  if (id === undefined) {
    return;
  }
  writeMessage({
    schema_version: SCHEMA_VERSION,
    id,
    error: { code, message },
  });
}

function buildManifest(): Record<string, unknown> {
  return {
    schema_version: SCHEMA_VERSION,
    name: PLUGIN_NAME,
    description: PLUGIN_DESCRIPTION,
    tools: [
      {
        name: TOOL_NAME,
        description: "Echo text back from the " + PLUGIN_NAME + " plugin.",
        parameters: {
          type: "object",
          properties: {
            text: {
              type: "string",
              description: "Text to echo back",
            },
          },
          required: ["text"],
        },
      },
    ],
  };
}

const rl = readline.createInterface({
  input: process.stdin,
  crlfDelay: Infinity,
});

rl.on("line", (rawLine: string) => {
  const line = rawLine.trim();
  if (!line) {
    return;
  }
  let reqId: number | undefined;
  try {
    const req = JSON.parse(line) as RPCRequest;
    reqId = req.id;
    const v = req.schema_version;
    if (v !== undefined && v !== null && v !== "" && v !== "1" && !(typeof v === "string" && v.startsWith("1."))) {
      throw new Error("unsupported schema_version " + JSON.stringify(v));
    }
    if (req.method === "shutdown") {
      if (reqId !== undefined) {
        writeMessage({ schema_version: SCHEMA_VERSION, id: reqId, result: {} });
      }
      rl.close();
      return;
    }
    let result: Record<string, unknown>;
    if (req.method === "manifest") {
      result = buildManifest();
    } else if (req.method === "tool.execute") {
      const name = req.params?.name ?? "";
      if (name !== TOOL_NAME) {
        result = { content: "unknown tool " + JSON.stringify(name), is_error: true };
      } else {
        const text = String(req.params?.arguments?.text ?? "");
        result = { content: PLUGIN_NAME + ": " + text };
      }
    } else {
      writeError(reqId, -32601, "unknown method " + JSON.stringify(req.method ?? ""));
      return;
    }
    if (reqId !== undefined) {
      writeMessage({ schema_version: SCHEMA_VERSION, id: reqId, result });
    }
  } catch (err) {
    writeError(reqId, -32000, err instanceof Error ? err.message : String(err));
  }
});
`, name, description, toolName)
}

func renderJavaScriptTemplate(name, description, toolName string) string {
	return fmt.Sprintf(`import * as readline from "node:readline";

const SCHEMA_VERSION = "1.0";
const PLUGIN_NAME = %q;
const PLUGIN_DESCRIPTION = %q;
const TOOL_NAME = %q;

function writeMessage(payload) {
  process.stdout.write(JSON.stringify(payload) + "\n");
}

function writeError(id, code, message) {
  if (id === undefined) {
    return;
  }
  writeMessage({
    schema_version: SCHEMA_VERSION,
    id,
    error: { code, message },
  });
}

function buildManifest() {
  return {
    schema_version: SCHEMA_VERSION,
    name: PLUGIN_NAME,
    description: PLUGIN_DESCRIPTION,
    tools: [
      {
        name: TOOL_NAME,
        description: "Echo text back from the " + PLUGIN_NAME + " plugin.",
        parameters: {
          type: "object",
          properties: {
            text: {
              type: "string",
              description: "Text to echo back",
            },
          },
          required: ["text"],
        },
      },
    ],
  };
}

const rl = readline.createInterface({
  input: process.stdin,
  crlfDelay: Infinity,
});

rl.on("line", (rawLine) => {
  const line = rawLine.trim();
  if (!line) {
    return;
  }
  let reqId;
  try {
    const req = JSON.parse(line);
    reqId = req.id;
    const v = req.schema_version;
    if (v !== undefined && v !== null && v !== "" && v !== "1" && !(typeof v === "string" && v.startsWith("1."))) {
      throw new Error("unsupported schema_version " + JSON.stringify(v));
    }
    if (req.method === "shutdown") {
      if (reqId !== undefined) {
        writeMessage({ schema_version: SCHEMA_VERSION, id: reqId, result: {} });
      }
      rl.close();
      return;
    }
    let result;
    if (req.method === "manifest") {
      result = buildManifest();
    } else if (req.method === "tool.execute") {
      const name = (req.params && req.params.name) || "";
      if (name !== TOOL_NAME) {
        result = { content: "unknown tool " + JSON.stringify(name), is_error: true };
      } else {
        const text = String((req.params && req.params.arguments && req.params.arguments.text) ?? "");
        result = { content: PLUGIN_NAME + ": " + text };
      }
    } else {
      writeError(reqId, -32601, "unknown method " + JSON.stringify(req.method || ""));
      return;
    }
    if (reqId !== undefined) {
      writeMessage({ schema_version: SCHEMA_VERSION, id: reqId, result });
    }
  } catch (err) {
    writeError(reqId, -32000, err instanceof Error ? err.message : String(err));
  }
});
`, name, description, toolName)
}
